import lzma
import base64
import os
import hashlib
import random
from cryptography.fernet import Fernet
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2HMAC


# 反调试和环境检查
import sys
import time
import inspect
import platform

def check_environment():
    """简单的环境验证"""
    # 检查是否在调试器中运行
    gettrace = getattr(sys, 'gettrace', None)
    if gettrace and gettrace():
        print("警告：检测到调试器")
        time.sleep(random.uniform(1, 3))  # 添加随机延迟

    # 检查是否在虚拟环境中运行
    if hasattr(sys, 'real_prefix') or (hasattr(sys, 'base_prefix') and sys.base_prefix != sys.prefix):
        print("注意：在虚拟环境中运行")

    # 稍微随机化执行流程
    if random.random() > 0.5:
        time.sleep(random.uniform(0.1, 0.3))

# 执行环境检查
check_environment()


# 加密参数
encrypted_data = ''
xor_key = 'isczbe4AFR/YWYNzlidEKg=='
salt = 'tu5j/DfgiSd6MwD1PV7TEA=='
password = '7bee3db365d14fca504388b2a0c02047'

def xor_decrypt(data, key):
    """XOR解密函数"""
    if isinstance(key, str):
        key = base64.b64decode(key.encode('utf-8'))

    # 创建循环密钥以匹配数据长度
    key_cycle = bytearray()
    for i in range(len(data)):
        key_cycle.append(key[i % len(key)])

    # 执行XOR操作
    result = bytearray()
    for i in range(len(data)):
        result.append(data[i] ^ key_cycle[i])

    return bytes(result)

def derive_key(password, salt):
    """从密码和盐派生Fernet密钥"""
    if isinstance(password, str):
        password = password.encode('utf-8')

    if isinstance(salt, str):
        salt = base64.b64decode(salt.encode('utf-8'))

    kdf = PBKDF2HMAC(
        algorithm=hashes.SHA256(),
        length=32,
        salt=salt,
        iterations=100000,
    )
    key = base64.urlsafe_b64encode(kdf.derive(password))
    return key

try:
    # 第4层：Base64解码
    encrypted_content = base64.b64decode(encrypted_data.encode('utf-8'))

    # 第3层：AES解密
    fernet_key = derive_key(password, salt)
    fernet = Fernet(fernet_key)
    xor_encrypted = fernet.decrypt(encrypted_content)

    # 第2层：XOR解密
    compressed_content = xor_decrypt(xor_encrypted, xor_key)

    # 第1层：LZMA解压缩
    script_content = lzma.decompress(compressed_content).decode('utf-8')

    # 执行解密后的代码
    exec(script_content)
except Exception as e:
    print(f"脚本执行过程中出错: {e}")
